  tradition: ['Tradition', 'Tradition'], tradition_hint: ['Every realm follows the tradition of its ruling culture\'s group.', 'Jedes Reich folgt der Tradition der Gruppe seiner herrschenden Kultur.'],
  diplomatic_standing: ['Diplomatic standing', 'Diplomatisches Ansehen'],
  diplomatic_standing_hint: ['Speeds envoys, raises others\' opinion of us and their willingness to accept our proposals, and deepens improved relations.', 'Beschleunigt Gesandte, hebt die Meinung anderer über uns und ihre Bereitschaft, unsere Vorschläge anzunehmen, und vertieft verbesserte Beziehungen.'],
  r_their_diplomacy: ['Their diplomacy', 'Ihre Diplomatie'], r_envoy_skill: ['Skill of our envoys', 'Geschick unserer Gesandten'],
  x_office_chancellor_does: ['Diplomacy {b} % (envoys faster, better opinion and answers), Governance research {b2} %.', 'Diplomatie {b} % (schnellere Gesandte, bessere Meinung und Antworten), Forschung in Verwaltung {b2} %.'],
  x_office_treasurer_does: ['Tax yield {b} %, less graft the abler he is, Commerce & Learning research {b2} %.', 'Steuerertrag {b} %, weniger Veruntreuung je fähiger er ist, Forschung in Handel & Gelehrsamkeit {b2} %.'],
  x_office_marshal_does: ['Discipline {b} %, morale, faster recruitment, Warfare research {b2} %.', 'Disziplin {b} %, Moral, schnellere Aushebung, Forschung im Kriegswesen {b2} %.'],
  x_office_chaplain_does: ['Conversion by our preachers (three times the bonus).', 'Bekehrung durch unsere Prediger (das Dreifache des Bonus).'],
  x_office_spymaster_does: ['Our clerks are discovered less often; foreign clerks are caught more often.', 'Unsere Schreiber werden seltener entdeckt; fremde Schreiber werden öfter gefasst.'],
  production_method: ['Production method', 'Produktionsweise'],
  production_method_hint: ['How the workshops of this town are organised. Changing it costs gold and can be done once a year.', 'Wie die Werkstätten dieser Stadt organisiert sind. Ein Wechsel kostet Gold und ist einmal im Jahr möglich.'],
  method_guild_hint: ['Masters, journeymen and apprentices under guild rules.', 'Meister, Gesellen und Lehrlinge nach Zunftordnung.'],
  method_putting_out_hint: ['Merchants hand out raw goods to households working at home: more output and more hands, a little more waste. Needs Commerce & Learning 6.', 'Verleger geben Rohwaren an Heimarbeiter aus: mehr Ausstoß und mehr Arbeitsplätze, etwas mehr Verschnitt. Braucht Handel & Gelehrsamkeit 6.'],
  method_manufactory_hint: ['Wage workers under one roof with divided labour: far more output from fewer hands and less material. Needs a manufactory.', 'Lohnarbeiter unter einem Dach mit geteilter Arbeit: viel mehr Ausstoß mit weniger Händen und weniger Material. Braucht eine Manufaktur.'],
  x_method_output: ['Output per worker', 'Ausstoß je Arbeiter'], x_method_inputs: ['Raw goods needed', 'Benötigte Rohwaren'], x_method_jobs: ['Workplaces', 'Arbeitsplätze'],
  x_employment: ['Employed', 'Beschäftigt'], x_employment_hint: ['Share of the artisans here who find work in the workshops.', 'Anteil der Handwerker hier, die in den Werkstätten Arbeit finden.'], method_switched: ['Workshops reorganised', 'Werkstätten umgestellt'],
  migration: ['Migration', 'Wanderung'], migration_hint: ['Peasants and labourers moving in (+) or away (−) last month, toward neighbouring land where the common people live better. Across borders fewer move, across a front none. Newcomers take up the free farms: a place that has taken in many draws fewer, one that many have left keeps the rest, so the flow dies down after a few percent.', 'Bauern und Tagelöhner, die letzten Monat zugezogen (+) oder fortgezogen (−) sind, hin zu Nachbarland, in dem das einfache Volk besser lebt. Über Grenzen ziehen weniger, über eine Front niemand. Zuzügler besetzen die freien Höfe: ein Ort, der viele aufgenommen hat, zieht weniger an, einer, den viele verlassen haben, hält den Rest. So versiegt der Strom nach wenigen Prozent.'],
