  cb_succession: ['Succession', 'Erbfolge'], cb_trade: ['Trade conflict', 'Handelskonflikt'], cb_situation: ['Cause of the situation', 'Anlass der Lage'],
  xw_cbhint_claim: ['A claim on their land.', 'Ein Anspruch auf ihr Land.'], xw_cbhint_gathering: ['They hold land of our people that we mean to gather.', 'Sie halten Land unseres Volkes, das wir sammeln wollen.'],
  xw_cbhint_fabricated: ['Forged charters from our clerks; they lapse after a time.', 'Gefälschte Urkunden unserer Schreiber; sie verfallen nach einer Weile.'],
  xw_cbhint_reconquest: ['They hold land that was ours within living memory (still our core).', 'Sie halten Land, das zu Lebzeiten unser war (noch unser Kernland).'],
  xw_cbhint_holy_war: ['Another faith family that holds holy places of ours, or a zealous ruler against an infidel neighbour.', 'Eine andere Glaubensfamilie, die unsere heiligen Stätten hält, oder ein eifriger Herrscher gegen einen ungläubigen Nachbarn.'],
  xw_cbhint_succession: ['Their ruler has no heir and is bound to our house by marriage or blood.', 'Ihr Herrscher hat keinen Erben und ist durch Heirat oder Blut mit unserem Haus verbunden.'],
  xw_cbhint_trade: ['They embargo us, tax our merchants with high tolls, or crowd our markets with theirs.', 'Sie verhängen ein Embargo, belegen unsere Kaufleute mit hohen Zöllen oder drängen in unsere Märkte.'],
  xw_cbhint_excommunicated: ['Their ruler is under the ban of our church.', 'Ihr Herrscher steht unter dem Bann unserer Kirche.'],
  xw_cbhint_independence: ['They are our overlord.', 'Sie sind unser Oberherr.'], xw_cbhint_rivalry: ['A rivalry justifies a war to humble them, never one of conquest.', 'Eine Rivalität rechtfertigt einen Krieg, um sie zu demütigen, nie einen Eroberungskrieg.'],
