  x_el_next_hint: ['When the emperor dies, the electors choose his successor. The list shows how they would vote today.', 'Stirbt der Kaiser, wählen die Kurfürsten seinen Nachfolger. Die Liste zeigt, wie sie heute stimmen würden.'],
  x_el_voted: ['Our vote is cast', 'Unsere Stimme ist abgegeben'], x_el_vote: ['Vote', 'Wählen'], x_el_why: ['Why this choice', 'Warum diese Wahl'], x_el_undecided: ['Undecided', 'Unentschieden'], x_el_for_us: ['What they think of us', 'Was sie von uns halten'],
  x_el_campaign_hint: ['Gifts for this elector (or, as emperor during a diet, for this member): +15 favour, up to 60. Favour fades by a fifth each year.', 'Geschenke für diesen Kurfürsten (oder als Kaiser während eines Reichstags für dieses Glied): +15 Gunst, bis 60. Die Gunst schwindet jedes Jahr um ein Fünftel.'],
  x_el_gifts: ['Gifts', 'Geschenke'], x_el_campaign: ['Gifts', 'Beschenken'], x_el_modal_hint: ['The emperor is dead. As an elector we cast our vote for his successor; the electors decide on', 'Der Kaiser ist tot. Als Kurfürst geben wir unsere Stimme für seinen Nachfolger ab; die Kurfürsten entscheiden am'],
  x_el_votes_now: ['Votes now', 'Stimmen jetzt'], x_el_own_hint: ['Hover over the votes to see why each elector leans as it does.', 'Fahrt über die Stimmen, um zu sehen, warum jeder Kurfürst so neigt.'], x_el_later: ['Decide later', 'Später entscheiden'],
  x_diet_title: ['Diet and imperial reforms', 'Reichstag und Reichsreformen'], x_diet_session: ['In session until', 'Tagt bis'], x_diet_needs: ['needs authority', 'braucht Autorität'], x_diet_next: ['next', 'als Nächstes'],
  x_diet_tally: ['Votes for : against', 'Stimmen dafür : dagegen'], x_diet_rule: ['Electors count three times. A reform passes with more votes for than against and at least two fifths of all votes, if imperial authority still covers its cost.', 'Kurfürsten zählen dreifach. Eine Reform gilt bei mehr Ja- als Nein-Stimmen und mindestens zwei Fünfteln aller Stimmen, wenn die Reichsautorität ihre Kosten noch deckt.'],
  x_diet_our_stance: ['Our stance', 'Unsere Haltung'], x_diet_ready: ['The diet can meet again from', 'Der Reichstag kann wieder tagen ab'], x_diet_need_auth: ['Not enough imperial authority', 'Nicht genug Reichsautorität'],
